<script setup lang="ts">
import {ref,onMounted} from 'vue';
import type {Bank,BankMember,LibraryQuestionSummary,QuestionVersion,Page} from '@survey/shared';
import {api} from '../api';
import {queryPage} from '../library-client';
import DefinitionView from './DefinitionView.vue';
import {materializeQuestion} from '@survey/shared';
const props=defineProps<{initialQuestionId?:string;disabled?:boolean}>(),emit=defineEmits<{selected:[version:QuestionVersion|null]}>(),uid=crypto.randomUUID(),scope=ref('own'),banks=ref<Bank[]>([]),bankCursor=ref<string|null>(null),bankId=ref(''),questions=ref<{id:string;title:string;selectable:boolean}[]>([]),questionCursor=ref<string|null>(null),questionId=ref(props.initialQuestionId??''),versions=ref<QuestionVersion[]>([]),versionCursor=ref<string|null>(null),versionId=ref(''),selected=ref<QuestionVersion|null>(null),busy=ref(false),error=ref('');
function clear(){versions.value=[];versionId.value='';versionCursor.value=null;selected.value=null;emit('selected',null);}
async function loadQuestions(more=false){busy.value=true;error.value='';if(!more){questionId.value='';clear();}try{
 if(scope.value==='bank'){if(!bankId.value){questions.value=[];return;}const p=await api<Page<BankMember>>(`/question-banks/${bankId.value}/members`+queryPage({limit:'20',cursor:more?questionCursor.value??undefined:undefined}));const rows=p.items.map(q=>({id:q.questionId,title:q.title??'当前不可选用',selectable:q.selectable}));questions.value=more?[...questions.value,...rows]:rows;questionCursor.value=p.nextCursor;}
 else{const p=await api<Page<LibraryQuestionSummary>>('/questions'+queryPage({scope:scope.value,limit:'20',cursor:more?questionCursor.value??undefined:undefined}));const rows=p.items.map(q=>({id:q.id,title:q.title,selectable:!!q.latestVersionId}));questions.value=more?[...questions.value,...rows]:rows;questionCursor.value=p.nextCursor;}
}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function loadBanks(more=false){try{const p=await api<Page<Bank>>('/question-banks'+queryPage({limit:'20',cursor:more?bankCursor.value??undefined:undefined}));banks.value=more?[...banks.value,...p.items]:p.items;bankCursor.value=p.nextCursor;}catch(e){error.value=(e as Error).message;}}
async function loadVersions(more=false){if(!questionId.value)return;busy.value=true;error.value='';if(!more)clear();try{const p=await api<Page<QuestionVersion>>(`/questions/${questionId.value}/versions`+queryPage({limit:'20',cursor:more?versionCursor.value??undefined:undefined}));versions.value=more?[...versions.value,...p.items]:p.items;versionCursor.value=p.nextCursor;}catch(e){error.value=(e as Error).message;clear();}finally{busy.value=false;}}
function choose(){selected.value=versions.value.find(v=>v.id===versionId.value)??null;emit('selected',selected.value);}
onMounted(async()=>{await loadBanks();if(props.initialQuestionId){await loadVersions();}else await loadQuestions();});
</script>
<template><div class="question-picker"><fieldset :disabled="disabled||busy"><label :for="`source-${uid}`">题目来源</label><select :id="`source-${uid}`" v-model="scope" @change="loadQuestions()"><option value="own">我的题目</option><option value="shared">共享给我</option><option value="bank">我的题库</option></select><template v-if="scope==='bank'"><label :for="`bank-${uid}`">题库</label><select :id="`bank-${uid}`" v-model="bankId" @change="loadQuestions()"><option value="">请选择题库</option><option v-for="b in banks" :key="b.id" :value="b.id">{{b.name}}</option></select><button v-if="bankCursor" type="button" class="quiet" @click="loadBanks(true)">更多题库</button></template>
<label :for="`question-${uid}`">选择题目</label><select :id="`question-${uid}`" v-model="questionId" @change="loadVersions()"><option value="">请选择</option><option v-if="initialQuestionId&&!questions.some(q=>q.id===initialQuestionId)" :value="initialQuestionId">当前实例的来源题目</option><option v-for="q in questions" :key="q.id" :value="q.id" :disabled="!q.selectable">{{q.title}}{{q.selectable?'':'（无可用正式版）'}}</option></select><button v-if="initialQuestionId&&!questions.length" type="button" class="quiet" @click="loadQuestions()">浏览其他可用题目（替换仅支持同题或直接派生首版）</button><button v-if="questionCursor" type="button" class="quiet" @click="loadQuestions(true)">更多题目</button>
<label :for="`version-${uid}`">正式版本</label><select :id="`version-${uid}`" v-model="versionId" @change="choose"><option value="">请明确选择一个正式版本</option><option v-for="v in versions" :key="v.id" :value="v.id">v{{v.version}} · {{v.content.title}}</option></select><button v-if="versionCursor" type="button" class="quiet" @click="loadVersions(true)">更多正式版本</button></fieldset><p v-if="busy" role="status" aria-busy="true">正在读取可用版本…</p><p v-if="error" role="alert" class="error">{{error}} <button class="quiet" @click="questionId?loadVersions():loadQuestions()">重新读取</button></p><p v-if="!busy&&!questions.length&&!initialQuestionId&&!error" class="muted">此来源暂时没有可选题目。题目需要先保存正式版本。</p><DefinitionView v-if="selected" :definition="{title:`将使用正式 v${selected.version}`,description:'固定选中版本，不会自动跟随作者后续修改。',questions:[materializeQuestion(selected.content,{required:false,jumpRules:[]},'selection-preview')]}"/></div></template>
